	Protocol   string      `json:"protocol,omitempty"`
	StepPolicy StepPolicy  `json:"step_policy,omitempty"`
	Agents     []AgentSpec `json:"agents"`
	Edges      []EdgeSpec  `json:"edges,omitempty"`
